import {
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  useEffect,
  useId,
  useCallback,
  useImperativeHandle,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/cn";
import { useGlide } from "@/lib/glide";
import { useSelectableCollection } from "./selectable.js";

/** Intrinsic focus and selection state supplied when rendering a Listbox item. */
export type ListboxItemState = {
  active: boolean;
  disabled: boolean;
  selected: boolean;
};

/** Props accepted by Listbox. */
export type ListboxProps<T, Multiple extends boolean = false> = {
  emptyMessage?: ReactNode;
  /** Returns the stable key used for focus and selection. */
  getKey: (item: T) => string;
  /** Returns the accessible label used for an item. */
  getLabel: (item: T) => string;
  /** Determines whether an item can receive focus or selection. */
  isDisabled?: (item: T) => boolean;
  items: readonly T[];
  /** Receives the selection control's root div. */
  rootRef?: React.Ref<HTMLDivElement>;
  /** Renders an item with its intrinsic focus and selection state. */
  renderItem?: (item: T, active: boolean, state: ListboxItemState) => ReactNode;
} & Omit<
  HTMLAttributes<HTMLDivElement>,
  "defaultValue" | "onChange" | "onSelect" | "value"
> &
  (Multiple extends true
    ? {
        defaultValue?: ListboxValue<true>;
        multiple: true;
        /** Receives the next value and selected item after local interaction. */
        onValueChange?: (value: ListboxValue<true>, item: T[]) => void;
        value?: ListboxValue<true>;
      }
    : Multiple extends false
      ? {
          defaultValue?: ListboxValue;
          multiple?: false;
          /** Receives the next value and selected item after local interaction. */
          onValueChange?: (value: ListboxValue, item: null | T) => void;
          value?: ListboxValue;
        }
      : | {
            defaultValue?: ListboxValue;
            multiple?: false;
            /** Receives the next value and selected item after local interaction. */
            onValueChange?: (value: ListboxValue, item: null | T) => void;
            value?: ListboxValue;
          }
        | {
            defaultValue?: ListboxValue<true>;
            multiple: true;
            /** Receives the next value and selected item after local interaction. */
            onValueChange?: (value: ListboxValue<true>, item: T[]) => void;
            value?: ListboxValue<true>;
          });

/** Supported ListboxValue values. */
export type ListboxValue<Multiple extends boolean = false> =
  Multiple extends true ? string[] : null | string;

/** A selection primitive with caller-owned values and intrinsic keyboard navigation. */
export function Listbox<T>(input: ListboxProps<T, boolean>) {
  const {
    className,
    defaultValue,
    emptyMessage = "No options",
    getKey,
    getLabel,
    id: providedId,
    isDisabled = () => false,
    items,
    multiple,
    onClick,
    onKeyDown,
    renderItem,
    rootRef,
    value: controlledValue,
    ...props
  } = input;
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const root = useRef<HTMLDivElement | null>(null);
  useImperativeHandle<HTMLDivElement | null, HTMLDivElement | null>(
    rootRef,
    () => root.current,
  );
  const glide = useGlide('[role="option"][data-active]');
  const attach = useCallback(
    (node: HTMLDivElement | null) => {
      root.current = node;
      glide(node);
    },
    [glide],
  );
  const isMultiple = multiple === true;
  const initialValue: ListboxValue<boolean> = isMultiple ? [] : null;
  const [uncontrolledValue, setUncontrolledValue] = useState<
    ListboxValue<boolean>
  >(() => defaultValue ?? initialValue);
  const selectedValue = optionalValueOr(controlledValue, uncontrolledValue);
  const selectedKeys = selectedKeysFor(selectedValue, isMultiple);
  const collection = useSelectableCollection({ getKey, isDisabled, items });
  const { enabledItems } = collection;
  const firstSelected = items.find((item) =>
    selectedKeys.includes(getKey(item)),
  );
  const { activeKey, activeItem, setActiveKey } = collection;
  const activeEnabled = activeItem;
  const controlledSelection =
    controlledValue === undefined
      ? undefined
      : JSON.stringify(
          isMultiple ? [...new Set(selectedKeys)].sort() : selectedKeys,
        );
  const previousControlledSelection = useRef(controlledSelection);
  const initialized = useRef(false);
  useEffect(() => {
    if (initialized.current || activeKey !== null) return;
    const initial = firstSelected ?? enabledItems[0];
    if (initial) {
      initialized.current = true;
      setActiveKey(getKey(initial));
    }
  }, [activeKey, enabledItems, firstSelected, getKey, setActiveKey]);
  useEffect(() => {
    if (
      controlledSelection !== undefined &&
      controlledSelection !== previousControlledSelection.current
    ) {
      const selectedItem = items.find(
        (item) => selectedKeys.includes(getKey(item)) && !isDisabled(item),
      );
      setActiveKey(selectedItem ? getKey(selectedItem) : null);
    }
    previousControlledSelection.current = controlledSelection;
  }, [controlledSelection, getKey, isDisabled, items, selectedKeys]);

  const commit = (item: T | undefined) => {
    if (!item || isDisabled(item)) return;
    const key = getKey(item);
    let nextKeys: string[];
    if (isMultiple) {
      nextKeys = selectedKeys.includes(key)
        ? selectedKeys.filter((selectedKey) => selectedKey !== key)
        : [...selectedKeys, key];
    } else {
      nextKeys = [key];
    }
    if (input.multiple) {
      if (controlledValue === undefined) setUncontrolledValue(nextKeys);
      input.onValueChange?.(
        nextKeys,
        items.filter((candidate) => nextKeys.includes(getKey(candidate))),
      );
    } else {
      const nextValue = nextKeys[0] ?? null;
      if (controlledValue === undefined) setUncontrolledValue(nextValue);
      input.onValueChange?.(nextValue, item);
    }
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented) return;
    if (event.key === "Escape") {
      return;
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      commit(activeEnabled);
      return;
    }
    if (enabledItems.length === 0) return;
    if (event.key === "ArrowDown") collection.move(1);
    else if (event.key === "ArrowUp") collection.move(-1);
    else if (event.key === "Home") collection.move(-1, "start");
    else if (event.key === "End") collection.move(1, "end");
    else return;
    event.preventDefault();
  };

  return (
    <div
      {...props}
      aria-activedescendant={
        activeEnabled
          ? `${id}-option-${encodeURIComponent(getKey(activeEnabled))}`
          : undefined
      }
      aria-multiselectable={isMultiple ? true : undefined}
      className={cn(
        "max-h-72 w-full overflow-auto rounded-box border border-base-300 bg-base-100 p-xs shadow-lg focus-visible:outline-none focus-visible:ring-2 caps-focus-color",
        className,
      )}
      id={id}
      onClick={onClick}
      onKeyDown={handleKeyDown}
      ref={attach}
      role="listbox"
      tabIndex={props.tabIndex ?? 0}
    >
      {items.length === 0 ? (
        <div className="px-md py-sm text-sm text-base-content">
          {emptyMessage}
        </div>
      ) : (
        items.map((item) => {
          const key = getKey(item);
          const disabled = isDisabled(item);
          const selected = selectedKeys.includes(key);
          const active = activeEnabled ? getKey(activeEnabled) === key : false;
          const state = { active, disabled, selected };
          return (
            <div
              aria-disabled={disabled || undefined}
              aria-selected={selected}
              data-active={(active && !disabled) || undefined}
              className={cn(
                "cursor-pointer rounded-field px-md py-sm text-sm outline-none",
                active && "bg-base-200",
                selected && "font-medium",
                disabled &&
                  "cursor-not-allowed bg-base-200 text-base-content outline outline-1 outline-dashed outline-base-300",
              )}
              id={`${id}-option-${encodeURIComponent(key)}`}
              key={key}
              onClick={(event) => {
                if (disabled) {
                  event.preventDefault();
                  return;
                }
                setActiveKey(key);
                commit(item);
              }}
              role="option"
            >
              {renderItem?.(item, active, state) ?? getLabel(item)}
            </div>
          );
        })
      )}
    </div>
  );
}

function selectedKeysFor(
  value: ListboxValue<boolean> | undefined,
  multiple: boolean,
): string[] {
  if (multiple) return Array.isArray(value) ? value.slice() : [];
  if (value === null || value === undefined || Array.isArray(value)) return [];
  return [value];
}

function optionalValueOr<Value>(
  value: Value | undefined,
  fallback: Value,
): Value {
  switch (value) {
    case undefined:
      return fallback;
    default:
      return value;
  }
}

import { useEffect, useMemo, useState } from "react";

export type SelectableCollectionOptions<T> = {
  getKey: (item: T) => string;
  isDisabled?: (item: T) => boolean;
  items: readonly T[];
};

export function useSelectableCollection<T>({
  getKey,
  isDisabled = () => false,
  items,
}: SelectableCollectionOptions<T>) {
  const enabledItems = useMemo(() => {
    const keys = items.map(getKey);
    if (keys.some((key) => !key))
      throw new Error("Selectable items require non-empty keys");
    if (new Set(keys).size !== keys.length)
      throw new Error("Selectable items require unique keys");
    return items.filter((item) => !isDisabled(item));
  }, [getKey, isDisabled, items]);
  const [activeKey, setActiveKey] = useState<string | null>(null);
  useEffect(() => {
    if (
      activeKey !== null &&
      !enabledItems.some((item) => getKey(item) === activeKey)
    )
      setActiveKey(null);
  }, [activeKey, enabledItems, getKey]);
  const activeItem = enabledItems.find((item) => getKey(item) === activeKey);
  const activeIndex = activeItem
    ? enabledItems.findIndex((item) => getKey(item) === activeKey)
    : -1;

  const move = (direction: 1 | -1, edge?: "start" | "end") => {
    if (enabledItems.length === 0) return;
    const nextIndex = edge
      ? edge === "start"
        ? 0
        : enabledItems.length - 1
      : activeIndex < 0
        ? direction > 0
          ? 0
          : enabledItems.length - 1
        : (activeIndex + direction + enabledItems.length) % enabledItems.length;
    const next = enabledItems[nextIndex];
    if (next) setActiveKey(getKey(next));
  };

  return {
    activeIndex,
    activeItem,
    activeKey,
    enabledItems,
    move,
    setActiveKey,
  };
}

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

import { useCallback, useRef, type RefCallback } from "react";

import { canAnimate, motionEasing, readMotion } from "./motion.js";

type Box = Readonly<{ x: number; y: number; width: number; height: number }>;

/**
 * The attribute a row carries while the glide stands in for its highlight:
 * empty while the stand-in travels, `measure` while its resting colour is read.
 */
const glideStandInAttribute = "data-glide-stand-in";

function boxIn(host: HTMLElement, element: Element): Box {
  const outer = host.getBoundingClientRect();
  const inner = element.getBoundingClientRect();
  // Host-relative and scroll-aware, so a scrolled list glides true.
  return {
    x: inner.left - outer.left + host.scrollLeft - host.clientLeft,
    y: inner.top - outer.top + host.scrollTop - host.clientTop,
    width: inner.width,
    height: inner.height,
  };
}

function place(box: Box) {
  return {
    transform: `translate(${String(box.x)}px, ${String(box.y)}px)`,
    width: `${String(box.width)}px`,
    height: `${String(box.height)}px`,
  };
}

/**
 * One highlight that glides between a list's rows instead of blinking from
 * row to row. `lit` selects the highlighted row (keyboard or pointer). While
 * the highlight moves, a single stand-in carrying that row's own resting
 * background and radius travels from the previous row and the rows' own
 * highlights are held back, so at rest every row looks exactly as it always
 * has. Within one open list the glide remembers its last row, so leaving and
 * re-entering glides from where it was. Timing and easing are the theme's;
 * reduced motion moves the highlight at once.
 */
export function useGlide(lit: string): RefCallback<HTMLElement> {
  const detach = useRef<(() => void) | null>(null);
  // A callback ref, so a list that mounts later (a popover's) still glides.
  return useCallback(
    (element: HTMLElement | null) => {
      detach.current?.();
      detach.current = element ? attachGlide(element, lit) : null;
    },
    [lit],
  );
}

function attachGlide(element: HTMLElement, lit: string): () => void {
  if (!canAnimate(element)) return () => undefined;
  const document = element.ownerDocument;
  let current: Element | null = element.querySelector(lit);
  let last: Box | null = current ? boxIn(element, current) : null;
  let ghost: HTMLSpanElement | null = null;
  let flight: Animation | null = null;
  const standIns = new Set<Element>();

  const release = () => {
    for (const row of standIns) row.removeAttribute(glideStandInAttribute);
    standIns.clear();
    if (ghost) ghost.hidden = true;
    flight = null;
  };

  const stage = () => {
    if (ghost) return ghost;
    const created = document.createElement("span");
    created.className = "caps-glide";
    created.setAttribute("aria-hidden", "true");
    element.prepend(created);
    // The stand-in paints above the list's background, below its rows.
    element.classList.add("caps-glide-host");
    if (getComputedStyle(element).position === "static")
      element.classList.add("caps-glide-anchor");
    ghost = created;
    return created;
  };

  const glide = (to: Element, away: Element | null) => {
    const motion = readMotion(element);
    const target = boxIn(element, to);
    const from = flight && ghost ? boxIn(element, ghost) : last;
    last = target;
    flight?.cancel();
    release();
    if (motion.reduced || from === null) return;
    if (Math.abs(from.y - target.y) < 1 && Math.abs(from.x - target.x) < 1)
      return;
    // Read the row's resting highlight, not a frame of its colour transition.
    to.setAttribute(glideStandInAttribute, "measure");
    const style = getComputedStyle(to);
    const background = style.backgroundColor;
    const radius = style.borderRadius;
    for (const row of [to, away]) {
      if (!row) continue;
      row.setAttribute(glideStandInAttribute, "");
      standIns.add(row);
    }
    const stand = stage();
    stand.hidden = false;
    stand.style.backgroundColor = background;
    stand.style.borderRadius = radius;
    const animation = stand.animate([place(from), place(target)], {
      duration: motion.normal,
      easing: motionEasing(motion, motion.ease),
      fill: "forwards",
    });
    flight = animation;
    animation.addEventListener("finish", () => {
      if (flight === animation) release();
    });
  };

  const update = () => {
    const next = element.querySelector(lit);
    if (next === current) return;
    const away = current;
    current = next;
    // A row that lights from nothing glides from the remembered row.
    if (next) glide(next, away);
  };

  const observer = new MutationObserver(update);
  observer.observe(element, {
    subtree: true,
    attributes: true,
    attributeFilter: [
      "data-highlighted",
      "data-active",
      "data-navigation",
      "aria-selected",
    ],
  });
  element.addEventListener("pointerover", update);
  element.addEventListener("pointerout", update);
  return () => {
    observer.disconnect();
    element.removeEventListener("pointerover", update);
    element.removeEventListener("pointerout", update);
    flight?.cancel();
    release();
    ghost?.remove();
  };
}

import {
  useLayoutEffect,
  useState,
  useSyncExternalStore,
  type RefObject,
} from "react";

/** Resolved, element-scoped motion. Times are milliseconds and distances pixels. */
export type Motion = Readonly<{
  reduced: boolean;
  squish: number;
  fast: number;
  normal: number;
  slow: number;
  springDuration: number;
  bounce: number;
  stretch: number;
  distance: number;
  stagger: number;
  blur: number;
  shake: number;
  steps: number;
  fuse: number;
  pressDepth: number;
  pressScale: number;
  ease: string;
  easeExit: string;
}>;

const defaults: Motion = Object.freeze({
  reduced: false,
  squish: 90,
  fast: 120,
  normal: 180,
  slow: 280,
  springDuration: 320,
  bounce: 0.3,
  stretch: 0.28,
  distance: 4,
  stagger: 24,
  blur: 0,
  shake: 3,
  steps: 0,
  fuse: 1,
  pressDepth: 0.5,
  pressScale: 1,
  ease: "cubic-bezier(0.2, 0, 0, 1)",
  easeExit: "cubic-bezier(0.4, 0, 1, 1)",
});

const preference = "(prefers-reduced-motion: reduce)";

/** Read at an event boundary; no root-theme lookup, so nested tokens win. */
export function readMotion(element: Element): Motion {
  const view = element.ownerDocument.defaultView;
  if (!view) return defaults;
  const style = view.getComputedStyle(element);
  const number = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    const parsed = Number.parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, parsed) : fallback;
  };
  const time = (name: string, fallback: number) => {
    const value = style.getPropertyValue(name).trim();
    return (
      number(name, fallback) *
      (value.endsWith("s") && !value.endsWith("ms") ? 1000 : 1)
    );
  };
  const browser: Partial<Pick<Window, "matchMedia">> = view;
  const reduced = browser.matchMedia?.(preference).matches ?? false;
  const duration = (name: string, fallback: number) =>
    reduced ? 120 : time(`--stipe-motion-${name}`, fallback);
  const amount = (name: string, fallback: number) =>
    reduced ? 0 : number(`--stipe-motion-${name}`, fallback);
  return {
    reduced,
    squish: duration("squish", defaults.squish),
    fast: duration("fast", defaults.fast),
    normal: duration("normal", defaults.normal),
    slow: duration("slow", defaults.slow),
    springDuration: duration("spring-duration", defaults.springDuration),
    bounce: Math.min(1, amount("bounce", defaults.bounce)),
    stretch: amount("stretch", defaults.stretch),
    distance: amount("distance", defaults.distance),
    stagger: reduced ? 0 : time("--stipe-motion-stagger", defaults.stagger),
    blur: amount("blur", defaults.blur),
    shake: amount("shake", defaults.shake),
    steps: Math.floor(amount("steps", defaults.steps)),
    fuse: number("--stipe-motion-fuse", defaults.fuse),
    pressDepth: reduced
      ? 0
      : number("--stipe-press-depth", defaults.pressDepth),
    pressScale: reduced
      ? 1
      : number("--stipe-press-scale", defaults.pressScale),
    ease: style.getPropertyValue("--stipe-motion-ease").trim() || defaults.ease,
    easeExit:
      style.getPropertyValue("--stipe-motion-ease-exit").trim() ||
      defaults.easeExit,
  };
}

/** Live motion tokens for a mounted ref, including nested theme and OS changes. */
export function useMotion(ref: RefObject<Element | null>): Motion {
  const [motion, setMotion] = useState<Motion>(() => ({
    ...defaults,
    reduced: true,
  }));
  useLayoutEffect(() => {
    const element = ref.current;
    const view = element?.ownerDocument.defaultView;
    if (!element || !view) return;
    const update = () => {
      const next = readMotion(element);
      setMotion((previous) =>
        JSON.stringify(previous) === JSON.stringify(next) ? previous : next,
      );
    };
    update();
    const observer = new view.MutationObserver(update);
    // Observe ancestors only: animation writes to descendants must not trigger reads.
    for (
      let parent: Element | null = element;
      parent;
      parent = parent.parentElement
    ) {
      observer.observe(parent, {
        attributes: true,
        attributeFilter: ["data-theme", "class", "style"],
      });
    }
    const browser: Partial<Pick<Window, "matchMedia">> = view;
    const media = browser.matchMedia?.(preference);
    media?.addEventListener("change", update);
    return () => {
      observer.disconnect();
      media?.removeEventListener("change", update);
    };
  }, [ref]);
  return motion;
}

/** Today's feel: the defaults that components' authored timings are written against. */
export const motionDefaults: Motion = defaults;

/**
 * Scale one of a component's authored durations by the theme's tempo
 * (`--stipe-motion-normal` against its 180ms default). Today's themes return
 * the authored value unchanged; reduced motion returns 0 (nothing travels).
 */
export function motionTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round((authored * motion.normal) / defaults.normal);
}

/**
 * Scale one of a component's authored spring bounces by the theme's bounce
 * (`--stipe-motion-bounce` against its 0.3 default), so a lively control stays
 * livelier than a calm one inside every theme. A 0 theme is critically damped.
 */
export function motionBounce(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  const scaled = (authored * motion.bounce) / defaults.bounce;
  return Math.min(0.9, Math.max(0, scaled));
}

/** Scale an authored spring settle time by `--stipe-motion-spring-duration`. */
export function motionSpringTime(motion: Motion, authored: number): number {
  if (motion.reduced) return 0;
  return Math.round(
    (authored * motion.springDuration) / defaults.springDuration,
  );
}

/** A CSS easing for a Web Animation, stepped when the theme asks for it. */
export function motionEasing(motion: Motion, ease: string): string {
  return motion.steps > 0 ? `steps(${String(motion.steps)}, end)` : ease;
}

/** Whether the element can run Web Animations (not in jsdom or old engines). */
export function canAnimate(element: Element): boolean {
  return "animate" in element;
}

const globalWindow: Partial<Pick<Window, "matchMedia">> = globalThis;

function prefersReducedMotion(): boolean {
  return globalWindow.matchMedia?.(preference).matches ?? false;
}

function subscribeReducedMotion(update: () => void) {
  const media = globalWindow.matchMedia?.(preference);
  media?.addEventListener("change", update);
  return () => {
    media?.removeEventListener("change", update);
  };
}

/** Server renders assume reduced motion, so hydration never starts mid-move. */
function serverReducedMotion() {
  return true;
}

/**
 * The live reduced-motion preference alone, for controls that only need to
 * know whether to move (their timing comes from `readMotion` when they do).
 */
export function useReducedMotion(): boolean {
  return useSyncExternalStore(
    subscribeReducedMotion,
    prefersReducedMotion,
    serverReducedMotion,
  );
}
